import { LitElement, html, css, nothing } from 'lit';
import { Fragment } from './aem/fragment.js';
import generateFragmentStore, { createPreviewDataWithParent } from './reactivity/source-fragment-store.js';
import { prepopulateFragmentCache } from './mas-repository.js';
import Store from './store.js';
import ReactiveController from './reactivity/reactive-controller.js';
import StoreController from './reactivity/store-controller.js';
import { CARD_MODEL_PATH, COLLECTION_MODEL_PATH, ODIN_PREVIEW_ORIGIN, PAGE_NAMES, TAG_PROMOTION_PREFIX } from './constants.js';
import router from './router.js';
import { VARIANTS } from './editors/variant-picker.js';
import { extractLocaleFromPath, generateCodeToUse, generateUniqueTitle, getFragmentMapping, replaceLocaleInPath, showToast } from './utils.js';
import { getSpectrumVersion } from './constants/icon-library.js';
import './editors/merch-card-editor.js';
import './editors/merch-card-collection-editor.js';
import './mas-variation-dialog.js';
import { getCountryName, getLocaleByCode } from '../../io/www/src/fragment/locales.js';
import { branch2Icon } from './icons.js';

const MODEL_WEB_COMPONENT_MAPPING = {
    [CARD_MODEL_PATH]: 'merch-card',
    [COLLECTION_MODEL_PATH]: 'merch-card-collection',
};

export default class MasFragmentEditor extends LitElement {
    static styles = css`
        #fragment-editor {
            display: flex;
            flex-direction: column;
            height: 100%;
            padding: 32px;
            max-width: 100%;
            margin: 0 auto;
            background: var(--spectrum-global-color-gray-75);
        }

        #breadcrumbs {
            margin-bottom: 32px;
        }

        sp-breadcrumbs {
            margin-bottom: 0;
        }

        sp-breadcrumb-item {
            cursor: pointer;
            color: var(--spectrum-global-color-gray-800);
            font-size: 14px;
        }

        sp-breadcrumb-item:hover {
            color: var(--spectrum-global-color-blue-600);
        }

        #editor-content {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 32px;
            flex: 1;
            padding-bottom: 48px;
        }

        @media (max-width: 1200px) {
            #editor-content {
                grid-template-columns: 1fr;
                overflow: auto;
            }
        }

        #form-column {
            padding-right: 16px;
        }

        #preview-column {
            position: sticky;
            top: 16px;
            height: fit-content;
            max-height: calc(100vh - 200px);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 16px;
        }

        #preview-wrapper {
            display: flex;
            flex-direction: column;
            align-items: center;
            margin: 0 auto;
            border-radius: 12px;
            box-shadow: 0 2px 8px 0 rgba(0, 0, 0, 0.16);
            overflow-y: auto;
        }

        @media (max-width: 1200px) {
            #preview-column {
                position: relative;
                max-height: none;
            }
        }

        .preview-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 16px 16px 0 16px;
            width: 100%;
            box-sizing: border-box;
        }

        .preview-header-title {
            font-size: 14px;
            font-weight: 400;
            color: var(--spectrum-global-color-gray-800);
        }

        .preview-content {
            padding: 32px;
            display: flex;
            flex-direction: column;
            align-items: flex-start;
            min-height: auto;
            position: relative;
            gap: 8px;
        }

        .cta-error-message {
            display: none;
            align-items: center;
            gap: 8px;
            padding: 8px 0;
            font-size: 14px;
            color: var(--merch-color-error);
        }

        .preview-content:has(a[is='checkout-link'].placeholder-failed) .cta-error-message {
            display: flex;
        }

        .section {
            background: var(--spectrum-global-color-gray-50);
            border: 1px solid var(--spectrum-global-color-gray-300);
            border-radius: 16px;
            padding: 32px;
            box-shadow: 0 2px 8px 0 rgba(0, 0, 0, 0.16);
        }

        .section-title {
            font-size: 20px;
            font-weight: 700;
            margin-bottom: 8px;
            color: var(--spectrum-global-color-gray-900);
            letter-spacing: -0.01em;
        }

        .section-description {
            font-size: 13px;
            color: var(--spectrum-global-color-gray-700);
            margin-bottom: 24px;
            line-height: 1.5;
        }

        mas-fragment-editor sp-field-group {
            margin-bottom: 16px;
        }

        mas-fragment-editor sp-divider {
            margin: 24px 0;
        }

        #loading-state {
            display: flex;
            align-items: center;
            justify-content: center;
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            z-index: 1;
        }

        .empty-state {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100%;
            min-height: 400px;
            color: var(--spectrum-global-color-gray-600);
        }

        .empty-state sp-icon {
            width: 64px;
            height: 64px;
            margin-bottom: 16px;
        }

        #missing-variation-panel {
            align-self: anchor-center;
            background: var(--spectrum-gray-50, #f8f8f8);
            border: 1px solid var(--spectrum-gray-300, #dadada);
            border-radius: 10px;
